#!/usr/bin/env python3
"""Summarize a local warehouse stock adjustment export."""

import json
import sys
from decimal import Decimal, InvalidOperation
from pathlib import Path


MAX_INPUT_BYTES = 8192

# The document size is already bounded, so Python's defensive decimal digit
# limit would otherwise reject valid, schema-sized mathematical integers.
if hasattr(sys, "set_int_max_str_digits"):
    sys.set_int_max_str_digits(0)


class InputError(Exception):
    """An invalid input document or an input that cannot be read."""


def _object_without_duplicates(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise InputError(f"duplicate object member: {key!r}")
        result[key] = value
    return result


def _reject_constant(value):
    raise InputError(f"invalid JSON number: {value}")


def _integer(value):
    # bool subclasses int, so test it explicitly. Decimal is used for JSON
    # number spellings with a decimal point or exponent, without float loss.
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value
    if isinstance(value, Decimal) and value.is_finite() and value == value.to_integral_value():
        try:
            return int(value)
        except (OverflowError, ValueError, InvalidOperation):
            return None
    return None


def summarize(document):
    if not isinstance(document, dict) or set(document) != {"adjustment_sheets"}:
        raise InputError("top-level object must contain only 'adjustment_sheets'")

    sheets = document["adjustment_sheets"]
    if not isinstance(sheets, dict) or not sheets:
        raise InputError("'adjustment_sheets' must be a nonempty object")

    reports = {}
    for identifier, sheet in sheets.items():
        if not identifier:
            raise InputError("sheet identifiers must be nonempty strings")
        if not isinstance(sheet, dict) or set(sheet) != {"stat", "turns"}:
            raise InputError(f"sheet {identifier!r} must contain only 'stat' and 'turns'")

        stat = sheet["stat"]
        turns = sheet["turns"]
        if stat not in ("net_units", "event_count", "largest_adjustment"):
            raise InputError(f"sheet {identifier!r} has an unknown stat")
        if not isinstance(turns, list):
            raise InputError(f"sheet {identifier!r} turns must be an array")

        values = []
        for value in turns:
            integer = _integer(value)
            if integer is None:
                raise InputError(f"sheet {identifier!r} contains a non-integer turn")
            values.append(integer)

        if stat == "net_units":
            reports[identifier] = sum(values)
        elif stat == "event_count":
            reports[identifier] = len(values)
        else:
            if not values:
                raise InputError(f"sheet {identifier!r} needs at least one turn")
            reports[identifier] = max(values)

    return {"stock_reports": reports}


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    if len(argv) != 2:
        print("usage: python3 summarize.py INPUT_JSON OUTPUT_JSON", file=sys.stderr)
        return 2

    input_path, output_path = map(Path, argv)
    try:
        with input_path.open("rb") as stream:
            raw = stream.read(MAX_INPUT_BYTES + 1)
        if len(raw) > MAX_INPUT_BYTES:
            raise InputError(f"input exceeds {MAX_INPUT_BYTES} bytes")
        try:
            source = raw.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise InputError("input is not valid UTF-8") from exc
        document = json.loads(
            source,
            parse_int=int,
            parse_float=Decimal,
            parse_constant=_reject_constant,
            object_pairs_hook=_object_without_duplicates,
        )
        result = summarize(document)
        serialized = json.dumps(result, ensure_ascii=False, separators=(",", ":")) + "\n"
        output_path.write_text(serialized, encoding="utf-8")
    except (OSError, UnicodeError, json.JSONDecodeError, InputError, ValueError) as exc:
        print(f"summarize.py: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
